import React, { useState } from 'react';
import './Booking.css';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import 'bootstrap/dist/css/bootstrap.min.css';

export default function RestaurantBooking() {
  const [formData, setFormData] = useState({
    location: '',
    cuisine: '',
    date: '',
    time: '',
    partySize: ''
  });

  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const navigate = useNavigate();

  const handleInputChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    try {
      // إرسال بيانات الحجز إلى الباك إند
      const response = await axios.post('/api/reservations', formData);

      // إذا تمت العملية بنجاح
      setMessage('تم الحجز بنجاح!');
      
      // ممكن نوجه المستخدم مثلاً إلى صفحة التأكيد أو صفحة الحجوزات
      // navigate('/my-reservations');

    } catch (error) {
      console.error(error);
      setMessage('حدث خطأ أثناء الحجز.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="background-image">
      <h1 className="text-center mb-5 text-white fw-bold">BOOK A TABLE</h1>
      <div className="container booking-container">
        {message && (
          <div className={`alert ${message.includes('خطأ') ? 'alert-danger' : 'alert-success'}`}>
            {message}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          <div className="row g-4">
            <div className="col-md-2">
              <label className="form-label text-dark">Location:</label>
              <input
                type="text"
                name="location"
                className="form-control"
                placeholder="اختر الموقع"
                value={formData.location}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Cuisine:</label>
              <input
                type="text"
                name="cuisine"
                className="form-control"
                placeholder="نوع المطبخ"
                value={formData.cuisine}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Date:</label>
              <input
                type="date"
                name="date"
                className="form-control"
                value={formData.date}
                onChange={handleInputChange}
                min={new Date().toISOString().split('T')[0]}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Time:</label>
              <input
                type="time"
                name="time"
                className="form-control"
                value={formData.time}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2">
              <label className="form-label text-dark">Party Size:</label>
              <input
                type="number"
                name="partySize"
                className="form-control"
                min="1"
                placeholder="عدد الأشخاص"
                value={formData.partySize}
                onChange={handleInputChange}
                required
              />
            </div>

            <div className="col-md-2 d-flex align-items-end">
              <button type="submit" className="btn btn-light w-100" disabled={loading}>
                {loading ? 'جاري الحجز...' : 'sertch'}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
}
